typedef float time_value_t;

class stringx
{
public:
  stringx(const stringx&);
  int length() const;
};

class TextString
{
public:
  char pad[75];
  struct color_type
  {
    unsigned char alpha;
    void set_alpha(int value) { alpha = value; }
  } color;
};

class MultiLineString
{
public:
  virtual void changeText(stringx text);
};

class FEMenu
{
public:
  char pad[100];
  FEMenu* parent;
  virtual void MakeActive(FEMenu* menu);
  void Update(time_value_t time_inc);
};

class FrontEnd
{
public:
  void Update(time_value_t time_inc);
};

class FEMultiMenu : public FEMenu
{
public:
  void Update(time_value_t time_inc)
  {
    ((FrontEnd*)((char*)this + 128))->Update(time_inc);
    FEMenu::Update(time_inc);
  }
};

extern stringx ksGlobalTextArray[];

enum
{
  GT_FE_CHEAT_UNLOCKED = 306,
  GT_FE_BAD_CHEAT_CODE,
  GT_FE_CHEAT_ALREADY_UNLOCKED
};

class EnterCheatMenu : public FEMultiMenu
{
public:
  char pad_to_current_code[256];
  stringx current_code;
  MultiLineString* code_display;
  TextString* cursor;
  char pad_to_closing[48];
  bool closing;
  char pad_to_closing_timer[7];
  float closing_timer;
  int cheat_unlocked;

  void Update(time_value_t time_inc);
};

static inline float fabs(float value)
{
  return __builtin_fabsf(value);
}

#define PHONE_CURSOR_PERIOD 0.25f
#define PHONE_CURSOR_INTENSITY 1.5f
#define CHEAT_CODE_MESSAGE_DURATION 1.0f
#define MAX_PHONE_NUM_LEN 10
#define CHEAT_INVALID_CODE -1

void EnterCheatMenu::Update(time_value_t time_inc)
{
	static float cursor_time = 0.0f;
	static float button_highlight_time = 0.0f;

	cursor_time += time_inc;
	if(cursor_time > PHONE_CURSOR_PERIOD)
		cursor_time = cursor_time - PHONE_CURSOR_PERIOD;
	// Make the cursor fade-blink
	int new_alpha = (int)fabs((cursor_time / PHONE_CURSOR_PERIOD * 2.0f - 1.0f) * 255 * PHONE_CURSOR_INTENSITY);
	if(new_alpha > 255)
		new_alpha = 255;
	cursor->color.set_alpha(new_alpha);

	if(closing)
	{
		closing_timer -= time_inc;
		if(closing_timer <= CHEAT_CODE_MESSAGE_DURATION)
		{
			// if it is a real code, display a success message
			if(cheat_unlocked >= 0)
				code_display->changeText(ksGlobalTextArray[GT_FE_CHEAT_UNLOCKED]);
			else if(current_code.length() == MAX_PHONE_NUM_LEN)
			{
				if(cheat_unlocked == CHEAT_INVALID_CODE)
					code_display->changeText(ksGlobalTextArray[GT_FE_BAD_CHEAT_CODE]);
				else
					code_display->changeText(ksGlobalTextArray[GT_FE_CHEAT_ALREADY_UNLOCKED]);
			}
			else // if exiting the menu without having typed in a full code
				closing_timer = 0.0f; // exit without a messge.
		}
		if(closing_timer <= 0.0f)
			parent->MakeActive(0);
	}
	FEMultiMenu::Update(time_inc);
}
